package core

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// The rows below come from Vim 9.2 with t_kb set to ^? (Backspace sends 0x7F,
// so CTRL-H arrives as its own key, as Bubble Tea reports it). There CTRL-H
// does what <BS> does in every mode, while mappings and the argument of
// r/f/t still tell the two apart. The clipboard starts as "REG"; normal-mode
// d, c and x don't write it yet, so rows that delete text have reg anyReg.
// Left out: rows whose <BS> twin already differs from Vim (d<BS>, y<BS>,
// c<BS>, visual o, curswant after v<BS>y, and '.' after an insert whose <BS>
// deleted nothing), r/f/t with CTRL-H (goeditor takes the letter, see the
// control characters note) and the / prompt, which the UI handles.

type testMap struct {
	modes   MapMode
	lhs     string
	rhs     string
	noremap bool
}

type ctrlHCase struct {
	name    string
	content string
	maps    []testMap
	keys    string // key notation
	text    string
	want    Position
	mode    Mode     // NormalMode when empty
	start   Position // visual start, checked in visual modes
	col     int      // Preferred, checked in normal mode
	reg     string
}

func runCtrlHCases(t *testing.T, tests []ctrlHCase) {
	t.Helper()
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			e, cb := newTestEditorWithClipboard(tt.content)
			cb.content = emptyRangeReg
			for _, m := range tt.maps {
				require.NoError(t, e.Map(m.modes, m.lhs, m.rhs, m.noremap))
			}
			typeKeys(t, e, tt.keys)
			mode := tt.mode
			if mode == "" {
				mode = NormalMode
			}
			assert.Equal(t, tt.text, content(e), "text")
			assert.Equal(t, tt.want, cursorPos(e), "cursor")
			assert.Equal(t, mode, e.GetState().Mode, "mode")
			switch mode {
			case VisualMode, VisualLineMode:
				assert.Equal(t, tt.start, e.GetState().VisualStart, "visual start")
			case NormalMode:
				assert.Equal(t, tt.col, e.GetBuffer().GetCursor().Preferred, "Preferred")
			}
			if tt.reg != anyReg {
				assert.Equal(t, tt.reg, cb.content, "register")
			}
		})
	}
}

// TestCtrlHInNormalMode checks that CTRL-H moves left like <BS>, across
// lines, with counts, and sets the column j and k go back to.
