// TestCtrlHAsLiteral checks that the argument of r is not rewritten to <BS>:
// r<BS> cancels, but r<C-h> replaces. Vim replaces with the ^H character;
// goeditor takes the letter until the control characters note is done.
func TestCtrlHAsLiteral(t *testing.T) {
	e := newTestEditor("abc")
	typeKeys(t, e, "r<C-h>")
	assert.NotEqual(t, "abc", content(e))

	e = newTestEditor("abc")
	typeKeys(t, e, "r<BS>")
	assert.Equal(t, "abc", content(e))
}
